        p_collar.addOrReplaceChild("collar_x5",
        CubeListBuilder.create()
                .texOffs(32, 17).addBox(-1f, 0f, -1.15f, 2f, 2f, 1f, new CubeDeformation(-0.25f, -0.25f, -0.3f))
                , PartPose.offset(0f, 0f, 0f));
        return LayerDefinition.create(mesh, 64, 64);
